FACTS. In plan-check.mjs taskBytes sizes a Files entry by its whole file, or for a .md file by the heading section that fits the task. A large CONTRIBUTING.md listed only because a few of its lines name another path from the same Files list is therefore counted at its section or full size, which pushes the task over the size limit. The fix counts such an entry by only the lines that mention another Files path of the task.
FAIL: the answer blames the limit constant, the bytes/4 token estimate, the task section text, or the way the Files list is parsed, or proposes raising the limit or exempting the file by name.
PASS: the answer finds that a listed file is sized by its whole file or heading section in taskBytes (sizeOf) and proposes counting a file that is listed only for a cross-reference by its matching lines instead.
Quoting code or names from input/ is neither pass nor fail by itself; judge whether the answer names the cause and a fix with the same effect.
Reference fix, the real commit 5fd939b8:
diff --git a/skills/spec/scripts/plan-check.mjs b/skills/spec/scripts/plan-check.mjs
index 67d0eb1c..6546dffc 100644
--- a/skills/spec/scripts/plan-check.mjs
+++ b/skills/spec/scripts/plan-check.mjs
@@ -155,12 +155,20 @@ function headingSectionBytes(text, taskText) {
   return Buffer.byteLength(section.join('\n'));
 }

+function referencingLinesBytes(text, others) {
+  const paths = others.map((other) => other.path).filter((otherPath) => !otherPath.endsWith('/'));
+  const matching = text.split('\n').filter((line) => paths.some((otherPath) => line.includes(otherPath)));
+  return matching.length === 0 ? null : Buffer.byteLength(matching.join('\n'));
+}
+
 function taskBytes(task, root, forkPoint) {
   const wholeSize = (file) => (forkPoint === null ? bytesUnder(path.join(root, file.path)) : bytesAtCommit(root, forkPoint, file.path));
   const textOf = (file) => (forkPoint === null ? textOnDisk(path.join(root, file.path)) : textAtCommit(root, forkPoint, file.path));
   const sizeOf = (file) => {
-    if (!file.path.endsWith('.md')) return wholeSize(file);
     const text = textOf(file);
+    const referencing = text === null ? null : referencingLinesBytes(text, task.files.filter((other) => other !== file));
+    if (referencing !== null) return referencing;
+    if (!file.path.endsWith('.md')) return wholeSize(file);
     return (text === null ? null : headingSectionBytes(text, task.section)) ?? wholeSize(file);
   };
   return Buffer.byteLength(task.section) + task.files.reduce((total, file) => total + sizeOf(file), 0);
